const isSameCell = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
  x1 === x2 && y1 === y2;

const contains = (cells: Cell[], cell: Cell): boolean =>
  cells.some((other) => isSameCell(cell, other));

const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x - 1, y],
  [x - 1, y + 1],
  [x, y - 1],
  [x, y + 1],
  [x + 1, y - 1],
  [x + 1, y],
  [x + 1, y + 1],
];

const candidates = (livingCells: Cell[]): Cell[] => {
  const result: Cell[] = [];
  for (const cell of [...livingCells, ...livingCells.flatMap(neighborsOf)]) {
    if (!contains(result, cell)) result.push(cell);
  }
  return result;
};

const survives = (cell: Cell, livingCells: Cell[]): boolean => {
  const liveNeighbors = countLiveNeighbors(cell, livingCells);
  if (contains(livingCells, cell)) return liveNeighbors === 2 || liveNeighbors === 3;
  return liveNeighbors === 3;
};

export const nextGeneration = (livingCells: Cell[]): Cell[] =>
  candidates(livingCells).filter((cell) => survives(cell, livingCells));
